-- =============================================================================
-- Shefaa — full restore, in one paste.
--
-- Supabase Dashboard -> SQL Editor -> New query -> paste all of this -> Run.
--
-- GENERATED FILE — do not edit. Run ./scripts/build-restore.sh instead.
-- Sources:
--   supabase/migrations/*.sql   (in order)
--   supabase/seed.sql
--   ../Shefaa_Admin_Panel/supabase/migrations/002_fix_rls_policies.sql
--
-- Safe to re-run: every statement is if-not-exists / on-conflict-do-nothing.
-- Two manual steps follow at the bottom.
-- =============================================================================

-- ############## 1 of 3 — SCHEMA ##############

-- ---- 0000_base_schema.sql ----
-- =============================================================================
-- Shefaa — Base schema for the patient app.
--
-- IMPORTANT — HOW THIS FILE CAME TO BE
-- This schema was RECONSTRUCTED by reading the Dart data models in `lib/`
-- (the column names the app actually reads and writes) plus the additive
-- migrations in the admin-panel and doctor-dashboard repos. It was NOT dumped
-- from the live database, because the live schema had never been committed
-- anywhere.
--
-- Treat it as a starting point, not as the authority. As soon as you have a
-- working database again, replace this file with a real dump:
--
--     supabase db dump --db-url "$DB_URL" -f supabase/migrations/0000_base_schema.sql
--
-- Every statement is idempotent (`if not exists`), so running it against a
-- database that still has its tables will not destroy anything.
-- =============================================================================

create extension if not exists "pgcrypto";

-- -----------------------------------------------------------------------------
-- Location hierarchy: Governorate -> City -> Clinic
-- Quoted capitalised names match what the app and admin panel already query.
-- -----------------------------------------------------------------------------
create table if not exists public."Governorates" (
  id         bigint generated by default as identity primary key,
  name       text not null,
  created_at timestamptz not null default now()
);

create table if not exists public."Cities" (
  id             bigint generated by default as identity primary key,
  governorate_id bigint references public."Governorates" (id) on delete cascade,
  name           text not null,
  created_at     timestamptz not null default now()
);

create table if not exists public."Clinics" (
  id         bigint generated by default as identity primary key,
  city_id    bigint references public."Cities" (id) on delete cascade,
  name       text not null,
  address    text,
  created_at timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- Specialties — read by the app's home screen (HomeRemoteDatasource).
-- -----------------------------------------------------------------------------
create table if not exists public.specialties (
  id          bigint generated by default as identity primary key,
  name        text not null,
  icon        text,
  name_ar     text,
  description text,
  color       text,
  base_fee    numeric(10,2) default 0,
  created_at  timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- Doctors — columns taken from DoctorModel.fromMap / toMap.
-- -----------------------------------------------------------------------------
create table if not exists public."Doctors" (
  id               bigint generated by default as identity primary key,
  name             text not null,
  title            text,
  specialization   text,
  specialty_id     bigint references public.specialties (id) on delete set null,
  clinic_id        bigint references public."Clinics" (id) on delete set null,
  image            text,
  location         text,
  rating           numeric(3,2) default 0 check (rating >= 0 and rating <= 5),
  consultation_fee numeric(10,2) not null default 0 check (consultation_fee >= 0),
  waiting_time     integer check (waiting_time >= 0),
  status           text not null default 'active',

  -- The other two apps depend on these: the admin panel writes email, and the
  -- doctor dashboard finds the signed-in doctor through user_id. Reconstructing
  -- this table from the Flutter models alone left them out.
  email            text,
  user_id          uuid references auth.users (id) on delete set null,
  phone            text,
  bio              text,
  license_number   text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create unique index if not exists doctors_user_id_key
  on public."Doctors" (user_id) where user_id is not null;
create unique index if not exists doctors_email_key
  on public."Doctors" (lower(email)) where email is not null;

create index if not exists doctors_specialty_idx on public."Doctors" (specialty_id);
create index if not exists doctors_clinic_idx    on public."Doctors" (clinic_id);

-- -----------------------------------------------------------------------------
-- Profiles — the patient record, keyed 1:1 to auth.users.
-- Written by AuthRemoteDataSource.register / read by ProfileRemoteDataSource.
-- -----------------------------------------------------------------------------
create table if not exists public.profiles (
  id         uuid primary key references auth.users (id) on delete cascade,
  name       text,
  phone      text,
  gender     text check (gender is null or gender in ('male', 'female')),
  birth_date date,
  status     text not null default 'active',
  created_at timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- Doctor availability — the bookable slots.
-- -----------------------------------------------------------------------------
create table if not exists public.doctor_availability (
  id         bigint generated by default as identity primary key,
  doctor_id  bigint not null references public."Doctors" (id) on delete cascade,
  date       date not null,
  start_time time not null,
  end_time   time not null,
  session    text not null check (session in ('morning', 'evening')),
  is_active  boolean not null default true,
  created_at timestamptz not null default now(),
  constraint doctor_availability_time_order check (end_time > start_time),
  -- A doctor cannot have the same slot listed twice.
  constraint doctor_availability_unique_slot unique (doctor_id, date, start_time)
);

create index if not exists doctor_availability_lookup_idx
  on public.doctor_availability (doctor_id, date, is_active);

-- -----------------------------------------------------------------------------
-- Payments — created alongside a booking.
-- -----------------------------------------------------------------------------
create table if not exists public.payments (
  id             bigint generated by default as identity primary key,
  patient_id     uuid references public.profiles (id) on delete set null,
  amount         numeric(10,2) not null check (amount >= 0),
  payment_method text not null check (payment_method in ('cash', 'instapay', 'card')),
  status         text not null default 'pending'
                   check (status in ('pending', 'paid', 'refunded', 'failed')),
  created_at     timestamptz not null default now()
);

create index if not exists payments_patient_idx on public.payments (patient_id);

-- -----------------------------------------------------------------------------
-- Bookings — the appointment itself.
-- -----------------------------------------------------------------------------
create table if not exists public.bookings (
  id          bigint generated by default as identity primary key,
  patient_id  uuid not null references public.profiles (id) on delete cascade,
  doctor_id   bigint not null references public."Doctors" (id) on delete cascade,
  payment_id  bigint references public.payments (id) on delete set null,
  booked_date date not null,
  start_time  time not null,
  end_time    time not null,
  -- 'no_show' matters for revenue: a patient who books and never arrives must be
  -- distinguishable from one who attended, or commission cannot be computed later.
  -- The doctor dashboard already sends this value (appointment.labels.ts).
  status      text not null default 'pending'
                check (status in ('pending', 'confirmed', 'completed', 'cancelled', 'no_show')),
  created_at  timestamptz not null default now()
);

create index if not exists bookings_patient_idx on public.bookings (patient_id);
create index if not exists bookings_doctor_idx  on public.bookings (doctor_id, booked_date);
create index if not exists bookings_status_idx  on public.bookings (status);

-- A doctor cannot be double-booked for the same slot. Cancelled bookings are
-- excluded so a cancelled slot can be rebooked.
create unique index if not exists bookings_no_double_booking
  on public.bookings (doctor_id, booked_date, start_time)
  where status <> 'cancelled';

-- -----------------------------------------------------------------------------
-- Admins — membership in this table is what grants admin-panel access.
-- Referenced by the is_admin() helper used in the RLS policies.
-- -----------------------------------------------------------------------------
create table if not exists public.admins (
  id         uuid primary key references auth.users (id) on delete cascade,
  name       text,
  created_at timestamptz not null default now()
);

-- Admin status comes from membership in public.admins and nothing else.
-- SECURITY DEFINER so the lookup is not itself filtered by admins' own RLS.
-- Defined here, with the table, because migrations that add policies depend on
-- it -- 0004 referenced it before the RLS migration had created it.
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.admins where id = auth.uid());
$$;

-- -----------------------------------------------------------------------------
-- Keep a profile row in step with every auth user, so a signup can never end up
-- with an auth account but no profile (the app currently inserts the profile
-- client-side, which silently fails when email confirmation is on).
-- -----------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, name)
  values (new.id, coalesce(new.raw_user_meta_data ->> 'name', split_part(new.email, '@', 1)))
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- -----------------------------------------------------------------------------
-- Table privileges for the Supabase roles.
--
-- RLS decides which rows a role sees; GRANT decides whether it may read the
-- table at all. Without this every app query fails with 42501, whatever the
-- policies say. Not `grant all`: that includes TRUNCATE, which ignores RLS.
-- -----------------------------------------------------------------------------
grant usage on schema public to anon, authenticated, service_role;
grant select, insert, update, delete on all tables in schema public to authenticated;
grant select on all tables in schema public to anon;
grant all on all tables in schema public to service_role;
grant usage, select on all sequences in schema public to anon, authenticated, service_role;

alter default privileges in schema public
  grant select, insert, update, delete on tables to authenticated;
alter default privileges in schema public
  grant select on tables to anon;
alter default privileges in schema public
  grant all on tables to service_role;
alter default privileges in schema public
  grant usage, select on sequences to anon, authenticated, service_role;

-- ---- 0002_allow_no_show_status.sql ----
-- =============================================================================
-- Allow 'no_show' on bookings.status.
--
-- The doctor dashboard offers "No show" as a status (its appointment.labels.ts
-- lists it alongside completed/cancelled) and calls updateStatus with it, but
-- the CHECK constraint in 0000_base_schema.sql did not permit the value, so the
-- action would have failed against the database with a constraint violation.
--
-- The distinction also matters for revenue: commission is owed on a visit that
-- happened, and a booking the patient never showed up for is not that. Without
-- a separate value both collapse into 'cancelled' and the history needed to
-- bill a clinic later is lost.
--
-- Run this only if you already applied 0000_base_schema.sql. Fresh installs
-- pick the value up from the corrected 0000.
-- =============================================================================

alter table public.bookings drop constraint if exists bookings_status_check;

alter table public.bookings add constraint bookings_status_check
  check (status in ('pending', 'confirmed', 'completed', 'cancelled', 'no_show'));

-- ---- 0003_grant_table_privileges.sql ----
-- =============================================================================
-- Grant table privileges to the Supabase roles.
--
-- PostgreSQL checks permissions in two layers:
--
--   1. GRANT       — may this role touch the table at all?
--   2. RLS policy  — which rows may it see or change?
--
-- 0000_base_schema.sql and 002_fix_rls_policies.sql set up layer 2 and left
-- layer 1 entirely to Supabase's default privileges. When those defaults do
-- not apply -- as happened here after the tables were dropped and recreated --
-- every query from the app fails with:
--
--   PostgrestException(message: permission denied for table specialties,
--                      code: 42501)
--
-- Note the difference in symptom: a row blocked by RLS comes back as an empty
-- result, never as an error. A 42501 is always a missing GRANT.
--
-- Safe to re-run.
-- =============================================================================

grant usage on schema public to anon, authenticated, service_role;

-- SELECT/INSERT/UPDATE/DELETE only -- deliberately NOT `grant all`, which
-- would include TRUNCATE. TRUNCATE is not subject to row level security, so
-- granting it would let any signed-in patient empty a table outright no matter
-- what the policies say.
grant select, insert, update, delete
  on all tables in schema public
  to authenticated;

grant select on all tables in schema public to anon;

-- Identity columns do not need this, but any serial column added later would.
grant usage, select on all sequences in schema public to anon, authenticated, service_role;

-- service_role runs behind the API and bypasses RLS by design; it is the role
-- an Edge Function uses to create a booking and its payment server-side.
grant all on all tables in schema public to service_role;

-- The same, for tables added from here on, so a new table is never invisible
-- to the app for this reason again.
alter default privileges in schema public
  grant select, insert, update, delete on tables to authenticated;

alter default privileges in schema public
  grant select on tables to anon;

alter default privileges in schema public
  grant all on tables to service_role;

alter default privileges in schema public
  grant usage, select on sequences to anon, authenticated, service_role;

-- ---- 0004_doctor_schedule.sql ----
-- =============================================================================
-- Weekly schedules, replacing the per-date availability rows.
--
-- doctor_availability stored one row per concrete date and time, so somebody
-- had to keep inserting rows forever. The seed generated 14 days; on day 15
-- every doctor would have shown no availability and the app would have said
-- "no slots" as though that were normal.
--
-- A doctor's working week is a pattern, so it is stored as one. Availability
-- for any date is computed from that pattern, which means it never expires and
-- changing the pattern needs no regeneration.
--
-- doctor_availability is NOT dropped here: the app still reads it. It goes when
-- the screens move over.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- The weekly pattern. 2-6 rows per doctor instead of thousands.
-- -----------------------------------------------------------------------------
create table if not exists public.doctor_schedule (
  id         bigint generated by default as identity primary key,
  doctor_id  bigint not null references public."Doctors" (id) on delete cascade,
  weekday    smallint not null check (weekday between 0 and 6),  -- 0 = Sunday, matching extract(dow)
  session    text not null check (session in ('morning', 'evening')),
  start_time time not null,
  end_time   time not null,

  -- How many patients the doctor takes in this session. Entered directly
  -- rather than derived from an average visit length: a dentist whose list
  -- mixes a 10-minute check with a 45-minute scaling knows their own number,
  -- and any average we computed would be worse than their estimate.
  capacity   integer not null check (capacity > 0),

  is_active  boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint doctor_schedule_time_order check (end_time > start_time),
  unique (doctor_id, weekday, session)
);

create index if not exists doctor_schedule_lookup_idx
  on public.doctor_schedule (doctor_id, weekday) where is_active;

-- -----------------------------------------------------------------------------
-- Exceptions: a holiday, or one day that runs differently.
--
-- session null  -> the whole day
-- is_closed     -> no clinic
-- capacity/times-> override just those, keeping the rest of the pattern
--
-- Known limit (accepted for v1): an exception adjusts a session the weekly
-- pattern already has. It cannot add a session on a weekday the doctor does
-- not normally work -- to open an extra Friday clinic, add Friday to the
-- pattern and remove it afterwards.
-- -----------------------------------------------------------------------------
create table if not exists public.doctor_schedule_exceptions (
  id         bigint generated by default as identity primary key,
  doctor_id  bigint not null references public."Doctors" (id) on delete cascade,
  date       date not null,
  session    text check (session in ('morning', 'evening')),
  is_closed  boolean not null default true,
  start_time time,
  end_time   time,
  capacity   integer check (capacity > 0),
  reason     text,
  created_at timestamptz not null default now(),
  constraint doctor_exception_time_order
    check (start_time is null or end_time is null or end_time > start_time),
  unique (doctor_id, date, session)
);

create index if not exists doctor_schedule_exceptions_lookup_idx
  on public.doctor_schedule_exceptions (doctor_id, date);

-- -----------------------------------------------------------------------------
-- bookings: a booking now belongs to a session, not to a 30-minute slot.
--
-- start_time/end_time are kept as a snapshot of the session window at the time
-- of booking, so a later change to the schedule does not rewrite history.
-- -----------------------------------------------------------------------------
alter table public.bookings
  add column if not exists session text
    check (session is null or session in ('morning', 'evening'));

-- The old index assumed one patient per (doctor, date, start_time). Under the
-- queue model everyone in a session shares the same window, so it would reject
-- the second booking of every session.
drop index if exists public.bookings_no_double_booking;

-- What actually needs preventing now: the same patient taking two places in
-- one session. Capacity is enforced when booking, against doctor_sessions_on.
create unique index if not exists bookings_one_place_per_session
  on public.bookings (doctor_id, patient_id, booked_date, session)
  where status <> 'cancelled';

create index if not exists bookings_session_queue_idx
  on public.bookings (doctor_id, booked_date, session, created_at)
  where status <> 'cancelled';

-- -----------------------------------------------------------------------------
-- What is available for one doctor on one date, after exceptions and bookings.
-- -----------------------------------------------------------------------------
create or replace function public.doctor_sessions_on(p_doctor bigint, p_date date)
returns table (
  session    text,
  start_time time,
  end_time   time,
  capacity   integer,
  booked     bigint,
  remaining  integer
)
language sql
stable
security invoker
set search_path = public
as $$
  with base as (
    select s.session, s.start_time, s.end_time, s.capacity
    from public.doctor_schedule s
    where s.doctor_id = p_doctor
      and s.weekday = extract(dow from p_date)::smallint
      and s.is_active
  ),
  applied as (
    select
      b.session,
      coalesce(ex.start_time, b.start_time) as start_time,
      coalesce(ex.end_time,   b.end_time)   as end_time,
      coalesce(ex.capacity,   b.capacity)   as capacity,
      -- a whole-day exception wins over a per-session one
      coalesce(day_ex.is_closed, ex.is_closed, false) as closed
    from base b
    left join public.doctor_schedule_exceptions ex
      on ex.doctor_id = p_doctor and ex.date = p_date and ex.session = b.session
    left join public.doctor_schedule_exceptions day_ex
      on day_ex.doctor_id = p_doctor and day_ex.date = p_date and day_ex.session is null
  )
  select
    a.session, a.start_time, a.end_time, a.capacity,
    count(bk.id) as booked,
    greatest(a.capacity - count(bk.id), 0)::integer as remaining
  from applied a
  left join public.bookings bk
    on  bk.doctor_id   = p_doctor
    and bk.booked_date = p_date
    and bk.session     = a.session
    and bk.status <> 'cancelled'
  where not a.closed
  group by a.session, a.start_time, a.end_time, a.capacity
  order by a.start_time;
$$;

-- -----------------------------------------------------------------------------
-- Queue position, computed rather than stored.
--
-- Stored numbers would need rewriting for everyone behind a cancellation, and
-- would race when two patients book at the same moment. Computed, a cancelled
-- booking simply drops out and the numbers behind it close up -- which is the
-- promise the patient is shown: your number can improve, never get worse.
-- -----------------------------------------------------------------------------
create or replace view public.booking_queue as
  select
    b.id as booking_id,
    b.doctor_id,
    b.patient_id,
    b.booked_date,
    b.session,
    b.status,
    row_number() over (
      partition by b.doctor_id, b.booked_date, b.session
      order by b.created_at, b.id
    )::integer as queue_number
  from public.bookings b
  where b.status <> 'cancelled';

-- -----------------------------------------------------------------------------
-- Row level security and grants.
--
-- Both, deliberately: policies without grants produce 42501 and are
-- unreachable, which is exactly how the last round broke.
-- -----------------------------------------------------------------------------
alter table public.doctor_schedule            enable row level security;
alter table public.doctor_schedule_exceptions enable row level security;

do $$
declare tbl text;
begin
  foreach tbl in array array['doctor_schedule', 'doctor_schedule_exceptions']
  loop
    -- every signed-in user may read: this is what the app shows as availability
    execute format('drop policy if exists sched_read_all on public.%I;', tbl);
    execute format(
      'create policy sched_read_all on public.%I
         for select to authenticated using (true);', tbl);

    -- only an admin may write, until doctors have accounts of their own;
    -- a doctor-owns-their-schedule policy lands with doctor login
    execute format('drop policy if exists sched_admin_write on public.%I;', tbl);
    execute format(
      'create policy sched_admin_write on public.%I
         for all to authenticated
         using (public.is_admin()) with check (public.is_admin());', tbl);
  end loop;
end $$;

grant select, insert, update, delete
  on public.doctor_schedule, public.doctor_schedule_exceptions
  to authenticated;
grant select on public.doctor_schedule, public.doctor_schedule_exceptions to anon;
grant all on public.doctor_schedule, public.doctor_schedule_exceptions to service_role;
grant usage, select on all sequences in schema public to anon, authenticated, service_role;

grant select on public.booking_queue to authenticated, anon, service_role;

revoke execute on function public.doctor_sessions_on(bigint, date) from public;
grant execute on function public.doctor_sessions_on(bigint, date)
  to anon, authenticated, service_role;

-- ---- 0005_doctor_accounts.sql ----
-- =============================================================================
-- Doctor logins: link a Doctors row to an auth account.
--
-- Nothing connected the three apps. The admin panel writes Doctors.email; the
-- doctor dashboard identifies a doctor through Doctors.user_id; the base schema
-- had neither column, so the admin panel's save would fail on an unknown column
-- and no doctor could ever sign in. Without that link the weekly schedule from
-- 0004 has nobody to edit it.
--
-- The link is made by matching a CONFIRMED email, in both directions, so it
-- works whichever happens first: the admin adding the doctor, or the doctor
-- signing up.
--
-- ############ READ THIS ############
-- The security of this rests on email confirmation being ON
-- (Authentication -> Providers -> Email -> Confirm email). With it off,
-- Supabase confirms every signup immediately, and anyone who knows a doctor's
-- email address could sign up with it and take over that doctor's dashboard.
-- Turn it on before any real doctor is added.
-- ###################################
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Columns the other two apps rely on, missing from the reconstructed schema.
-- -----------------------------------------------------------------------------
alter table public."Doctors" add column if not exists email          text;
alter table public."Doctors" add column if not exists user_id        uuid;
alter table public."Doctors" add column if not exists phone          text;
alter table public."Doctors" add column if not exists bio            text;
alter table public."Doctors" add column if not exists license_number text;
alter table public."Doctors" add column if not exists updated_at     timestamptz not null default now();

do $$ begin
  alter table public."Doctors"
    add constraint doctors_user_id_fkey
    foreign key (user_id) references auth.users (id) on delete set null;
exception when duplicate_object then null; end $$;

-- One auth account is one doctor.
create unique index if not exists doctors_user_id_key
  on public."Doctors" (user_id) where user_id is not null;

-- Two doctors cannot claim the same address, or a match would be ambiguous.
create unique index if not exists doctors_email_key
  on public."Doctors" (lower(email)) where email is not null;

-- -----------------------------------------------------------------------------
-- 2. Which doctor is signed in. The dashboard's RLS is built on this.
-- -----------------------------------------------------------------------------
create or replace function public.current_doctor_id()
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select id from public."Doctors" where user_id = auth.uid() limit 1;
$$;

revoke execute on function public.current_doctor_id() from public;
grant execute on function public.current_doctor_id() to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 3. The link itself.
--
-- Claims only a doctor row that is still unclaimed, and only from an account
-- whose address is confirmed. Both conditions matter: the first stops a second
-- account stealing a linked doctor, the second is what makes "owns the address"
-- mean anything.
-- -----------------------------------------------------------------------------
create or replace function public.link_doctor_account(p_user_id uuid, p_email text)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_doctor_id bigint;
begin
  if p_user_id is null or p_email is null or p_email = '' then
    return null;
  end if;

  update public."Doctors"
     set user_id = p_user_id,
         updated_at = now()
   where lower(email) = lower(p_email)
     and user_id is null
  returning id into v_doctor_id;

  return v_doctor_id;
end;
$$;

-- Direction A: the doctor signs up (or confirms) after the admin added them.
create or replace function public.on_auth_user_confirmed()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.email_confirmed_at is not null then
    perform public.link_doctor_account(new.id, new.email);
  end if;
  return new;
end;
$$;

drop trigger if exists on_auth_user_confirmed_link_doctor on auth.users;
create trigger on_auth_user_confirmed_link_doctor
  after insert or update of email_confirmed_at on auth.users
  for each row execute function public.on_auth_user_confirmed();

-- Direction B: the admin adds the doctor after they already have an account.
create or replace function public.on_doctor_email_set()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
begin
  if new.email is null or new.user_id is not null then
    return new;
  end if;

  select u.id into v_user_id
    from auth.users u
   where lower(u.email) = lower(new.email)
     and u.email_confirmed_at is not null
   limit 1;

  if v_user_id is not null
     and not exists (select 1 from public."Doctors" d where d.user_id = v_user_id) then
    new.user_id := v_user_id;
  end if;

  return new;
end;
$$;

drop trigger if exists on_doctor_email_set_link_account on public."Doctors";
create trigger on_doctor_email_set_link_account
  before insert or update of email on public."Doctors"
  for each row execute function public.on_doctor_email_set();

-- -----------------------------------------------------------------------------
-- 4. A linked doctor owns their own schedule.
--
-- 0004 left writing to admins only, because there was no way to be a doctor.
-- There is now, so add the doctor's own access beside it. Policies are OR-ed,
-- so this widens write access to exactly "the admin, or this doctor".
-- -----------------------------------------------------------------------------
do $$
declare tbl text;
begin
  foreach tbl in array array['doctor_schedule', 'doctor_schedule_exceptions']
  loop
    execute format('drop policy if exists sched_doctor_write on public.%I;', tbl);
    execute format(
      'create policy sched_doctor_write on public.%I
         for all to authenticated
         using (doctor_id = public.current_doctor_id())
         with check (doctor_id = public.current_doctor_id());', tbl);
  end loop;
end $$;

-- A doctor may edit their own row, but not create or delete doctors, and not
-- reassign the row to another account.
drop policy if exists doctors_self_update on public."Doctors";
create policy doctors_self_update on public."Doctors"
  for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- ---- 0006_queue_counts_see_all_bookings.sql ----
-- =============================================================================
-- Queue numbers and remaining places were computed under the caller's own RLS.
--
-- doctor_sessions_on was declared `security invoker`, so its
--
--     count(bk.id) ... from public.bookings bk
--
-- ran under the caller's policies -- and bookings_select_own limits a patient to
-- `patient_id = auth.uid()`. The count it needs is precisely the one RLS hides.
--
-- Measured on a session that really held 2 bookings:
--
--     patient who already booked   -> booked = 1, remaining = 9
--     patient about to book        -> booked = 0, remaining = 10
--
-- So every patient was told they were first in line however full the session
-- `remaining` never reached zero, so a full session never showed as full.
--
-- The fix is `security definer`. It is the right tool here and not a hole: the
-- function returns aggregates only -- session, times, capacity, a count -- and
-- never a row that identifies a patient. search_path is pinned, as it must be.
--
-- NOTE this does not stop two patients racing for the last place; the capacity
-- check is still advisory, enforced by the UI. A database-level guard is a
-- separate change.
-- =============================================================================

create or replace function public.doctor_sessions_on(p_doctor bigint, p_date date)
returns table (
  session    text,
  start_time time,
  end_time   time,
  capacity   integer,
  booked     bigint,
  remaining  integer
)
language sql
stable
-- definer, not invoker: counting how full a session is means counting other
-- people's bookings, which the caller's own policies hide from them.
security definer
set search_path = public
as $$
  with base as (
    select s.session, s.start_time, s.end_time, s.capacity
    from public.doctor_schedule s
    where s.doctor_id = p_doctor
      and s.weekday = extract(dow from p_date)::smallint
      and s.is_active
  ),
  applied as (
    select
      b.session,
      coalesce(ex.start_time, b.start_time) as start_time,
      coalesce(ex.end_time,   b.end_time)   as end_time,
      coalesce(ex.capacity,   b.capacity)   as capacity,
      -- a whole-day exception wins over a per-session one
      coalesce(day_ex.is_closed, ex.is_closed, false) as closed
    from base b
    left join public.doctor_schedule_exceptions ex
      on ex.doctor_id = p_doctor and ex.date = p_date and ex.session = b.session
    left join public.doctor_schedule_exceptions day_ex
      on day_ex.doctor_id = p_doctor and day_ex.date = p_date and day_ex.session is null
  )
  select
    a.session, a.start_time, a.end_time, a.capacity,
    count(bk.id) as booked,
    greatest(a.capacity - count(bk.id), 0)::integer as remaining
  from applied a
  left join public.bookings bk
    on  bk.doctor_id   = p_doctor
    and bk.booked_date = p_date
    and bk.session     = a.session
    and bk.status <> 'cancelled'
  where not a.closed
  group by a.session, a.start_time, a.end_time, a.capacity
  order by a.start_time;
$$;

revoke execute on function public.doctor_sessions_on(bigint, date) from public;
grant execute on function public.doctor_sessions_on(bigint, date)
  to anon, authenticated, service_role;

-- -----------------------------------------------------------------------------
-- booking_queue: right numbers, but it was handing them out for every booking.
--
-- The view is `security_invoker = false` (the default), so it runs as its owner
-- and computes row_number() over every booking -- which is what makes the queue
-- number correct. The same thing meant any signed-in patient could read the
-- whole view: every booking's patient_id, doctor, date and session.
--
-- Rank over everyone, then hand back only the rows the caller is entitled to.
-- The ranking still counts the bookings it no longer shows.
-- -----------------------------------------------------------------------------
create or replace view public.booking_queue as
  with ranked as (
    select
      b.id as booking_id,
      b.doctor_id,
      b.patient_id,
      b.booked_date,
      b.session,
      b.status,
      row_number() over (
        partition by b.doctor_id, b.booked_date, b.session
        order by b.created_at, b.id
      )::integer as queue_number
    from public.bookings b
    where b.status <> 'cancelled'
  )
  select
    r.booking_id,
    r.doctor_id,
    r.patient_id,
    r.booked_date,
    r.session,
    r.status,
    r.queue_number
  from ranked r
  where r.patient_id = auth.uid()
     or r.doctor_id  = public.current_doctor_id()
     or public.is_admin();

grant select on public.booking_queue to authenticated, service_role;

-- anon has no bookings and no doctor, so every row was already filtered out for
-- it. Dropping the grant says so rather than leaving it to the filter.
revoke select on public.booking_queue from anon;

-- ---- 0007_enforce_session_capacity.sql ----
-- =============================================================================
-- Capacity was advisory. The database now enforces it.
--
-- 0006 made `remaining` truthful, so the app hides a full session. That is a
-- screen, not a rule: two patients tapping "book" at the same moment both read
-- the last free place and both take it, because under READ COMMITTED neither
-- transaction can see the other's uncommitted row. Nothing in the database said
-- no.
--
-- The guard is a trigger that takes a transaction advisory lock on the session
-- before counting, so bookings for the same doctor, day and session are handled
-- one at a time. The lock is keyed on the session and released at commit: a
-- different session, day or doctor never waits.
--
-- Capacity comes from doctor_sessions_on so there is one definition of what a
-- session holds -- the weekly schedule with that day's exceptions applied --
-- rather than a second copy here that could drift from it.
-- =============================================================================

create or replace function public.enforce_session_capacity()
returns trigger
language plpgsql
-- definer for the same reason doctor_sessions_on is: counting how full a
-- session is means counting other patients' bookings, which the caller's own
-- policies hide. A patient must not be able to book past a limit simply
-- because row level security stops them seeing who is already in it.
security definer
set search_path = public
as $$
declare
  v_capacity integer;
  v_booked   integer;
begin
  -- A cancellation frees a place, it never takes one.
  if new.status = 'cancelled' then
    return new;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      new.doctor_id::text || '|' || new.booked_date::text || '|' || new.session,
      0
    )
  );

  select s.capacity into v_capacity
    from public.doctor_sessions_on(new.doctor_id, new.booked_date) s
   where s.session = new.session;

  -- No row means the doctor does not hold that session on that date at all --
  -- not on the weekly schedule, or closed by an exception.
  if v_capacity is null then
    -- The message is for the log; `hint` is the part callers match on, so a
    -- patient can be told this in their own language without the database
    -- holding a copy of one app's wording.
    raise exception 'Doctor holds no % session on %', new.session, new.booked_date
      using errcode = 'check_violation', hint = 'session_not_offered';
  end if;

  -- Counted here rather than taken from doctor_sessions_on's `booked`: that
  -- function is STABLE, so it reads the calling statement's snapshot, which was
  -- taken before this transaction waited for the lock. This count runs in a
  -- volatile trigger and sees what the transaction ahead of us committed.
  select count(*) into v_booked
    from public.bookings b
   where b.doctor_id   = new.doctor_id
     and b.booked_date = new.booked_date
     and b.session     = new.session
     and b.status     <> 'cancelled'
     -- On UPDATE the row is already in the table; it must not count itself.
     and b.id is distinct from new.id;

  if v_booked >= v_capacity then
    raise exception 'Session is full: % of % places taken', v_booked, v_capacity
      using errcode = 'check_violation', hint = 'session_full';
  end if;

  return new;
end;
$$;

revoke execute on function public.enforce_session_capacity() from public;

drop trigger if exists bookings_enforce_capacity on public.bookings;
create trigger bookings_enforce_capacity
  before insert or update of doctor_id, booked_date, session, status
  on public.bookings
  for each row execute function public.enforce_session_capacity();

-- -----------------------------------------------------------------------------
-- Tidying up after 0006: doctor_sessions_on became security definer there, and
-- it is still granted to anon. Nothing signed out can reach this app -- every
-- read policy is `to authenticated` -- so anon holding a function that now
-- bypasses row level security is an inconsistency, not a feature.
-- -----------------------------------------------------------------------------
revoke execute on function public.doctor_sessions_on(bigint, date) from anon;

-- =============================================================================
-- Booking became something that can be refused, so it has to be one step.
--
-- The app made two calls: insert a payment, then insert a booking. Two calls
-- are two transactions. Before this migration the second one practically never
-- failed; now "this session is full" is an ordinary outcome, and the payment
-- row from the first call would be left behind with nothing pointing at it --
-- money recorded for a visit that was refused. A patient cannot delete it
-- either (payments_delete_admin), so it would simply accumulate.
--
-- One function, one transaction: if the capacity trigger refuses the booking,
-- the payment goes with it.
-- =============================================================================

create or replace function public.create_booking(
  p_doctor  bigint,
  p_date    date,
  p_session text,
  p_start   time,
  p_end     time,
  p_amount  numeric,
  p_method  text
)
returns table (booking_id bigint, queue_number integer)
language plpgsql
-- definer so the queue number below counts every booking in the session, not
-- just the caller's. Everything it writes is pinned to auth.uid(), so it can
-- only ever create a booking for whoever is calling it.
security definer
set search_path = public
as $$
declare
  v_patient uuid := auth.uid();
  v_payment bigint;
  v_booking bigint;
  v_created timestamptz;
  v_queue   integer;
begin
  if v_patient is null then
    raise exception 'No authenticated user'
      using errcode = 'insufficient_privilege', hint = 'not_signed_in';
  end if;

  -- Said plainly here rather than let bookings_one_place_per_session surface as
  -- a duplicate key error the patient cannot read.
  if exists (
    select 1 from public.bookings b
     where b.patient_id  = v_patient
       and b.doctor_id   = p_doctor
       and b.booked_date = p_date
       and b.session     = p_session
       and b.status     <> 'cancelled'
  ) then
    raise exception 'Patient already holds a place in this session'
      using errcode = 'unique_violation', hint = 'already_booked';
  end if;

  insert into public.payments (patient_id, amount, payment_method, status)
  values (v_patient, p_amount, p_method, 'pending')
  returning id into v_payment;

  insert into public.bookings
    (patient_id, doctor_id, payment_id, booked_date, session,
     start_time, end_time, status)
  values (v_patient, p_doctor, v_payment, p_date, p_session,
          p_start, p_end, 'confirmed')
  returning id, created_at into v_booking, v_created;

  -- Same ordering as the booking_queue view, so the number the patient is told
  -- now is the number they will keep seeing.
  select count(*)::integer into v_queue
    from public.bookings b
   where b.doctor_id   = p_doctor
     and b.booked_date = p_date
     and b.session     = p_session
     and b.status     <> 'cancelled'
     and (b.created_at, b.id) <= (v_created, v_booking);

  return query select v_booking, v_queue;
end;
$$;

revoke execute on function
  public.create_booking(bigint, date, text, time, time, numeric, text) from public;
grant execute on function
  public.create_booking(bigint, date, text, time, time, numeric, text)
  to authenticated, service_role;

-- ---- 0008_booking_access_by_role.sql ----
-- =============================================================================
-- A doctor could not see a single one of their own bookings.
--
-- bookings_select_own is `patient_id = auth.uid() or is_admin()`. A doctor
-- signed into the dashboard is neither, so every query the dashboard makes came
-- back empty -- measured on a doctor with two bookings: 0 rows. The Appointments
-- page has been blank for every doctor since the policies were written, and
-- nothing that moves the queue along can be built on top of that.
--
-- These policies are OR-ed with the existing ones, so they widen access to
-- exactly "the patient, an admin, or the doctor this booking is with".
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Preconditions. Run out of order, this file fails deep inside a function body
-- with `relation "public.Doctors" does not exist`, which says nothing about
-- which migration is actually missing. Say it plainly instead.
-- -----------------------------------------------------------------------------
do $$
declare missing text[] := '{}';
begin
  if to_regclass('public.bookings') is null then
    missing := missing || 'bookings (migration 0000)'::text;
  end if;
  if to_regclass('public.profiles') is null then
    missing := missing || 'profiles (migration 0000)'::text;
  end if;
  if to_regproc('public.is_admin') is null then
    missing := missing || 'is_admin() (migration 0000)'::text;
  end if;
  if to_regproc('public.current_doctor_id') is null then
    missing := missing || 'current_doctor_id() (migration 0005)'::text;
  end if;

  if array_length(missing, 1) is not null then
    raise exception
      'Run the earlier migrations first. Missing: %', array_to_string(missing, ', ')
      using hint = 'run_migrations_in_order';
  end if;
end $$;

-- Answering "is this one of my patients?" means reading bookings that the
-- caller's own policies may hide, so it is asked by a definer function that
-- returns nothing but a boolean about the caller's own practice.
--
-- It asks current_doctor_id() who the caller is rather than joining "Doctors"
-- again: one definition of "which doctor am I", and one less table this file
-- has to know the name of.
create or replace function public.is_my_patient(p_patient uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
      from public.bookings b
     where b.doctor_id = public.current_doctor_id()
       and b.patient_id = p_patient
  );
$$;

revoke execute on function public.is_my_patient(uuid) from public;
grant execute on function public.is_my_patient(uuid) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- The doctor's own bookings.
--
-- current_doctor_id() is null for a patient, and `doctor_id = null` is never
-- true, so this policy is invisible to everyone who is not a linked doctor.
-- -----------------------------------------------------------------------------
drop policy if exists bookings_select_doctor on public.bookings;
create policy bookings_select_doctor on public.bookings
  for select to authenticated
  using (doctor_id = public.current_doctor_id());

-- Marking a patient seen, or not seen. RLS cannot restrict this to the status
-- column -- that is a column privilege, and `authenticated` needs table-wide
-- UPDATE for the patient's own cancel -- so a doctor can in principle edit
-- other fields of their own bookings. Moving one is still subject to the
-- capacity trigger, and they cannot hand it to another doctor: the check
-- clause pins doctor_id to them.
drop policy if exists bookings_update_doctor on public.bookings;
create policy bookings_update_doctor on public.bookings
  for update to authenticated
  using (doctor_id = public.current_doctor_id())
  with check (doctor_id = public.current_doctor_id());

-- -----------------------------------------------------------------------------
-- The names of the patients who booked them -- and nothing more than that:
-- a profile becomes visible only once that patient has a booking with them.
-- -----------------------------------------------------------------------------
drop policy if exists profiles_select_my_patients on public.profiles;
create policy profiles_select_my_patients on public.profiles
  for select to authenticated
  using (public.is_my_patient(id));

-- =============================================================================
-- What a patient may change about a booking: whether they are coming.
--
-- bookings_update_own lets a patient write any column of their own row, because
-- row level security grants access per row, not per column. So a patient could
-- mark their own booking `completed` -- the status commission is charged on --
-- or set a completed one back to cancelled and erase it. They could also move
-- it to another date while keeping their original created_at, which is the
-- field the queue is ordered by: booked early, jump the queue on a later day.
--
-- The app only ever cancels. This says so.
-- =============================================================================

create or replace function public.guard_booking_changes()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- No JWT at all means this is not an app user: the service role, a migration,
  -- or the SQL editor. Those already have full access to the table; the rules
  -- below are about what someone signed into the apps may do. Without this the
  -- trigger locks the owner out of her own database.
  if auth.uid() is null then
    return new;
  end if;

  -- The doctor this booking is with, and an admin, decide everything about it.
  if public.is_admin() or old.doctor_id = public.current_doctor_id() then
    return new;
  end if;

  -- Nobody else may move a booking: not to another doctor, another day,
  -- another session, or another patient.
  if new.doctor_id   is distinct from old.doctor_id
     or new.patient_id  is distinct from old.patient_id
     or new.booked_date is distinct from old.booked_date
     or new.session     is distinct from old.session then
    raise exception 'A booking cannot be moved; cancel and book again'
      using errcode = 'check_violation', hint = 'booking_immutable';
  end if;

  -- And the only status a patient may set is cancelled. Whether they actually
  -- turned up is the doctor's to record.
  if new.status is distinct from old.status and new.status <> 'cancelled' then
    raise exception 'A patient may only cancel'
      using errcode = 'check_violation', hint = 'cancel_only';
  end if;

  return new;
end;
$$;

revoke execute on function public.guard_booking_changes() from public;

drop trigger if exists bookings_guard_changes on public.bookings;
create trigger bookings_guard_changes
  before update on public.bookings
  for each row execute function public.guard_booking_changes();

-- ---- 0009_queue_now_serving.sql ----
-- =============================================================================
-- Which number the doctor is on right now.
--
-- A patient's queue number is a ticket: it is their place in the booking order
-- and it does not change as people are seen. That is the right behaviour -- a
-- clinic calls "number five" and you keep number five -- but it left the app
-- saying something false. The booking card reads
--
--     "دورك رقم 3 · قدامك 2"
--
-- and computes "2 ahead" as `queue_number - 1`, which counts everyone who
-- booked earlier whether or not the doctor has already seen them. Once the
-- dashboard's queue page is in use and the doctor starts marking patients seen,
-- that number is wrong from the first tap.
--
-- What was missing is the other half of a clinic display: not just your ticket,
-- but the number being served. Everything needed is already in the table; the
-- patient simply cannot see it, because row level security hides other people's
-- bookings from them -- which is exactly why it belongs in this view, which
-- ranks over every booking and hands back only what the caller may have.
--
-- now_serving is the lowest queue number in the session that has not been dealt
-- with, and null once everyone has. It is a number, never a name: nothing here
-- tells one patient anything about another.
-- =============================================================================

create or replace view public.booking_queue as
  with ranked as (
    select
      b.id as booking_id,
      b.doctor_id,
      b.patient_id,
      b.booked_date,
      b.session,
      b.status,
      row_number() over (
        partition by b.doctor_id, b.booked_date, b.session
        order by b.created_at, b.id
      )::integer as queue_number
    from public.bookings b
    where b.status <> 'cancelled'
  ),
  -- A second pass: queue_number cannot be read by a window function in the
  -- same select that computes it.
  serving as (
    select
      r.*,
      min(r.queue_number) filter (where r.status not in ('completed', 'no_show'))
        over (partition by r.doctor_id, r.booked_date, r.session) as now_serving
    from ranked r
  )
  select
    s.booking_id,
    s.doctor_id,
    s.patient_id,
    s.booked_date,
    s.session,
    s.status,
    s.queue_number,
    s.now_serving
  from serving s
  where s.patient_id = auth.uid()
     or s.doctor_id  = public.current_doctor_id()
     or public.is_admin();

grant select on public.booking_queue to authenticated, service_role;
revoke select on public.booking_queue from anon;

-- ---- 0010_queue_visible_to_trusted_roles.sql ----
-- =============================================================================
-- booking_queue was invisible to everyone except a patient or their doctor --
-- including the database owner.
--
-- 0006 narrowed the view to "your own rows" with
--
--     where patient_id = auth.uid()
--        or doctor_id  = current_doctor_id()
--        or is_admin()
--
-- which was right for the two API roles and wrong for everybody else. A view's
-- WHERE clause is not row level security: it applies to every caller, so it
-- also caught the connections that are trusted by definition.
--
--   postgres (the SQL editor)  -> 0 rows, while the table held bookings.
--                                 The owner could not inspect her own queue,
--                                 which is exactly what you reach for when a
--                                 queue number looks wrong.
--   service_role               -> ERROR: permission denied for function
--                                 is_admin. Not even a wrong answer: the view
--                                 cannot be read at all, because is_admin() was
--                                 only ever granted to `authenticated`.
--
-- Neither is a security boundary worth keeping. Both roles can already read
-- public.bookings directly; all the view was doing was making the queue harder
-- to look at than the table it is built from.
-- =============================================================================

create or replace view public.booking_queue as
  with ranked as (
    select
      b.id as booking_id,
      b.doctor_id,
      b.patient_id,
      b.booked_date,
      b.session,
      b.status,
      row_number() over (
        partition by b.doctor_id, b.booked_date, b.session
        order by b.created_at, b.id
      )::integer as queue_number
    from public.bookings b
    where b.status <> 'cancelled'
  ),
  serving as (
    select
      r.*,
      min(r.queue_number) filter (where r.status not in ('completed', 'no_show'))
        over (partition by r.doctor_id, r.booked_date, r.session) as now_serving
    from ranked r
  )
  select
    s.booking_id,
    s.doctor_id,
    s.patient_id,
    s.booked_date,
    s.session,
    s.status,
    s.queue_number,
    s.now_serving
  from serving s
  -- Named roles rather than `auth.uid() is null`: anon reaches PostgREST with
  -- no sub claim either, and this must not become a way for it to read every
  -- booking if the grant below is ever loosened.
  where current_user not in ('anon', 'authenticated')
     or s.patient_id = auth.uid()
     or s.doctor_id  = public.current_doctor_id()
     or public.is_admin();

grant select on public.booking_queue to authenticated, service_role;
revoke select on public.booking_queue from anon;

-- is_admin() was granted to `authenticated` alone, so anything the service role
-- touched that calls it failed outright. It reports on the caller and tells a
-- caller nothing it does not already know about itself.
grant execute on function public.is_admin() to service_role;

-- ---- 0011_signup_carries_profile_details.sql ----
-- =============================================================================
-- Registering with email confirmation on lost the patient's details.
--
-- The app writes the name, phone, gender and birth date to `profiles` itself,
-- straight after signUp. That only works when signUp hands back a session --
-- which it does only while email confirmation is off. Turn confirmation on and
-- there is no session, the write fails on row level security, and the patient
-- is left with whatever this trigger put there: a name guessed from the part
-- of their address before the @.
--
-- That is why confirmation is still off, and confirmation being off is what the
-- warning in 0005 is about: anyone who knows a doctor's address can sign up
-- with it and take over their dashboard. This is the half that has to be fixed
-- before that one can be closed.
--
-- So the details travel with the signup itself, as user metadata, and this
-- trigger writes them. It runs as the definer inside the signup transaction,
-- before any session exists, so it works either way.
-- =============================================================================

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  begin
    insert into public.profiles (id, name, phone, gender, birth_date)
    values (
      new.id,
      coalesce(
        nullif(new.raw_user_meta_data ->> 'name', ''),
        split_part(new.email, '@', 1)
      ),
      nullif(new.raw_user_meta_data ->> 'phone', ''),
      -- profiles.gender has a CHECK; anything else is dropped rather than
      -- allowed to fail the insert.
      case
        when new.raw_user_meta_data ->> 'gender' in ('male', 'female')
        then new.raw_user_meta_data ->> 'gender'
      end,
      -- Same for the date: validated by shape before it is cast, because a
      -- cast that throws here would throw inside signup.
      case
        when new.raw_user_meta_data ->> 'birth_date' ~ '^\d{4}-\d{2}-\d{2}$'
        then (new.raw_user_meta_data ->> 'birth_date')::date
      end
    )
    on conflict (id) do nothing;

  exception when others then
    -- A trigger on auth.users that raises makes the signup itself fail. No
    -- detail on a profile is worth refusing to create the account over, so
    -- fall back to the row this trigger has always written and let the person
    -- fix the rest from the profile screen.
    insert into public.profiles (id, name)
    values (new.id, split_part(new.email, '@', 1))
    on conflict (id) do nothing;
  end;

  return new;
end;
$$;

-- ---- 0012_home_banners.sql ----
-- =============================================================================
-- Banners for the patient app's home screen, managed from the admin panel.
--
-- The home screen carried a search bar that did nothing for months; the banner
-- replacing it must not become the same thing. So it is content, not code: rows
-- in a table and files in a bucket, changed from the admin panel without a new
-- build of the app.
-- =============================================================================

create table if not exists public.banners (
  id         bigint generated by default as identity primary key,
  image_url  text not null,
  -- Shown over the image. Optional: a banner may be all picture.
  title      text,
  subtitle   text,
  -- Lower first. Ties fall back to id, so the order is always total.
  sort_order integer not null default 0,
  is_active  boolean not null default true,
  created_at timestamptz not null default now()
);

create index if not exists banners_active_order_idx
  on public.banners (sort_order, id) where is_active;

alter table public.banners enable row level security;

-- A patient sees the active ones. An admin sees all of them, including the
-- ones they have switched off, or they could not switch them back on.
drop policy if exists banners_read on public.banners;
create policy banners_read on public.banners
  for select to authenticated
  using (is_active or public.is_admin());

drop policy if exists banners_admin_write on public.banners;
create policy banners_admin_write on public.banners
  for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

grant select, insert, update, delete on public.banners to authenticated;
grant all on public.banners to service_role;
grant usage, select on all sequences in schema public
  to anon, authenticated, service_role;

-- -----------------------------------------------------------------------------
-- The bucket the admin panel uploads into.
--
-- Guarded, because the storage schema is a Supabase thing: without this guard
-- the file cannot be run against a plain PostgreSQL, which is where these
-- migrations are tested.
-- -----------------------------------------------------------------------------
do $$
begin
  if to_regclass('storage.buckets') is null then
    raise notice 'storage schema not present -- skipping bucket setup';
    return;
  end if;

  -- public: the images are shown to every patient, so they are served straight
  -- from the CDN rather than through a signed URL per view.
  insert into storage.buckets (id, name, public)
  values ('banners', 'banners', true)
  on conflict (id) do nothing;

  -- Reading is public by the bucket flag above. Writing is the admin's alone --
  -- an authenticated patient must not be able to put files in the app's own
  -- home screen.
  execute 'drop policy if exists banners_insert_admin on storage.objects';
  execute $p$
    create policy banners_insert_admin on storage.objects
      for insert to authenticated
      with check (bucket_id = 'banners' and public.is_admin())
  $p$;

  execute 'drop policy if exists banners_update_admin on storage.objects';
  execute $p$
    create policy banners_update_admin on storage.objects
      for update to authenticated
      using (bucket_id = 'banners' and public.is_admin())
      with check (bucket_id = 'banners' and public.is_admin())
  $p$;

  execute 'drop policy if exists banners_delete_admin on storage.objects';
  execute $p$
    create policy banners_delete_admin on storage.objects
      for delete to authenticated
      using (bucket_id = 'banners' and public.is_admin())
  $p$;
end $$;

-- ---- 0013_location_tables_readable_and_locked.sql ----
-- =============================================================================
-- The location hierarchy: readable by everyone, writable by the admin only.
--
-- Two things brought this on.
--
-- 1. The app is about to read Governorates, Cities and Clinics for the city
--    picker. If row level security is on with no select policy, those reads
--    come back as zero rows -- not as an error -- and the picker would look
--    broken for no visible reason.
--
-- 2. 0003 granted insert, update and delete on every table in the schema to
--    `authenticated`. On a table with row level security switched off, that
--    grant is the whole answer: any signed-in patient could rename a clinic or
--    delete a governorate. Turning security on with a read-only policy for
--    patients is what closes that.
--
-- Safe to re-run.
-- =============================================================================

do $$
declare
  t text;
begin
  foreach t in array array['Governorates', 'Cities', 'Clinics'] loop
    if to_regclass(format('public.%I', t)) is null then
      raise notice 'table public.% not present -- skipping', t;
      continue;
    end if;

    execute format('alter table public.%I enable row level security', t);

    -- Where the clinics are is not private. A patient has to be able to read
    -- this before signing in, or the picker is empty on the signup screen.
    execute format('drop policy if exists %I on public.%I', t || '_read', t);
    execute format($p$
      create policy %I on public.%I
        for select to anon, authenticated
        using (true)
    $p$, t || '_read', t);

    -- Everything else is the admin panel's, and nobody else's.
    execute format('drop policy if exists %I on public.%I', t || '_admin_write', t);
    execute format($p$
      create policy %I on public.%I
        for all to authenticated
        using (public.is_admin()) with check (public.is_admin())
    $p$, t || '_admin_write', t);
  end loop;
end $$;

-- Speeds up the two lookups the picker makes: the cities of a governorate, and
-- the clinics of a city.
create index if not exists cities_governorate_idx
  on public."Cities" (governorate_id);

create index if not exists clinics_city_idx
  on public."Clinics" (city_id);

-- ---- 0014_appointment_windows.sql ----
-- =============================================================================
-- A booking is a window to arrive in, not a place in a queue.
--
-- The queue number was wrong and could not be made right. It ranked bookings by
-- when they were made, among the patients who used the app -- while the clinic
-- calls people in the order they walk in, and most of them never booked at all.
-- A patient told "you are number 3" arrived to find seven people ahead of them.
--
-- So the app stops promising a position and promises a window instead, which is
-- something it can keep. The doctor chooses which shape their day takes:
--
--   slot_minutes is null  ->  one window, the whole session: "6:00 - 9:00 pm"
--   slot_minutes = 60     ->  hourly windows: "9-10", "10-11", "11-12" ...
--
-- Null is the default, and it is what every existing row gets, so nothing
-- changes for a doctor who does not touch the setting.
--
-- Inside a window the clinic works exactly as it does today, first come first
-- served, and a walk-in costs the app nothing because the app never claimed an
-- order.
--
-- Safe to re-run.
-- =============================================================================

alter table public.doctor_schedule
  add column if not exists slot_minutes integer;

alter table public.doctor_schedule
  drop constraint if exists doctor_schedule_slot_minutes_positive;
alter table public.doctor_schedule
  add constraint doctor_schedule_slot_minutes_positive
  check (slot_minutes is null or slot_minutes > 0);

comment on column public.doctor_schedule.slot_minutes is
  'Length of each bookable window in minutes. Null means the whole session is '
  'one window, which is how a first-come-first-served clinic actually runs.';

-- Deliberately NOT added to doctor_schedule_exceptions. The other overrides
-- there work by coalesce, and null is a meaningful value here -- it is what
-- "one window" means -- so an exception could turn windows on for a day but
-- never off again. A half-working override is worse than none.

-- -----------------------------------------------------------------------------
-- doctor_sessions_on: the same shape as before, one row per bookable window
-- rather than one per session. A session with slot_minutes null yields exactly
-- one row, which is what it yielded before this migration, so every caller
-- keeps working unchanged.
-- -----------------------------------------------------------------------------
create or replace function public.doctor_sessions_on(p_doctor bigint, p_date date)
returns table (
  session    text,
  start_time time,
  end_time   time,
  capacity   integer,
  booked     bigint,
  remaining  integer
)
language sql
stable
-- definer, not invoker: counting how full a window is means counting other
-- people's bookings, which the caller's own policies hide from them.
security definer
set search_path = public
as $$
  with base as (
    select s.session, s.start_time, s.end_time, s.capacity, s.slot_minutes
    from public.doctor_schedule s
    where s.doctor_id = p_doctor
      and s.weekday = extract(dow from p_date)::smallint
      and s.is_active
  ),
  applied as (
    select
      b.session,
      coalesce(ex.start_time, b.start_time) as start_time,
      coalesce(ex.end_time,   b.end_time)   as end_time,
      coalesce(ex.capacity,   b.capacity)   as capacity,
      b.slot_minutes,
      -- a whole-day exception wins over a per-session one
      coalesce(day_ex.is_closed, ex.is_closed, false) as closed
    from base b
    left join public.doctor_schedule_exceptions ex
      on ex.doctor_id = p_doctor and ex.date = p_date and ex.session = b.session
    left join public.doctor_schedule_exceptions day_ex
      on day_ex.doctor_id = p_doctor and day_ex.date = p_date and day_ex.session is null
  ),
  counted as (
    select
      a.*,
      (a.end_time - a.start_time) as span,
      case
        when a.slot_minutes is null then 1
        else greatest(
          ceil(
            extract(epoch from (a.end_time - a.start_time))
              / (a.slot_minutes * 60.0)
          )::integer,
          1
        )
      end as window_count
    from applied a
    where not a.closed
  ),
  windows as (
    select
      c.session,
      (c.start_time + (c.span * g.i / c.window_count))::time as start_time,
      -- least() in interval space rather than on the times themselves: a window
      -- that overshoots must stop at the end of the session, and `time` wraps
      -- past midnight instead of clamping.
      (c.start_time + least(c.span * (g.i + 1) / c.window_count, c.span))::time
        as end_time,
      -- Integer division on the running total, not capacity/windows: the parts
      -- then add up to the capacity exactly instead of losing or inventing a
      -- place to rounding. 10 places over 3 windows gives 3, 3, 4.
      (c.capacity * (g.i + 1) / c.window_count)
        - (c.capacity * g.i / c.window_count) as capacity
    from counted c
    cross join lateral generate_series(0, c.window_count - 1) as g(i)
  )
  select
    w.session,
    w.start_time,
    w.end_time,
    w.capacity,
    count(bk.id) as booked,
    greatest(w.capacity - count(bk.id), 0)::integer as remaining
  from windows w
  left join public.bookings bk
    on  bk.doctor_id   = p_doctor
    and bk.booked_date = p_date
    and bk.session     = w.session
    -- The window, not the session. For a session that is one window the two are
    -- the same time, so bookings made before this migration still match.
    and bk.start_time  = w.start_time
    and bk.status <> 'cancelled'
  -- A capacity too small to spread leaves empty windows; they are not bookable
  -- and showing them would be offering a place that does not exist.
  where w.capacity > 0
  group by w.session, w.start_time, w.end_time, w.capacity
  order by w.start_time;
$$;

revoke execute on function public.doctor_sessions_on(bigint, date) from public;
grant execute on function public.doctor_sessions_on(bigint, date)
  to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Capacity belongs to the window now, not to the whole session.
--
-- Without this a six-hour day split into six windows would still be counted as
-- one pot: every patient could pick the 9-10 window and the trigger would wave
-- them through until the session's total was reached -- which is the exact
-- crowd the windows exist to spread out.
-- -----------------------------------------------------------------------------
create or replace function public.enforce_session_capacity()
returns trigger
language plpgsql
-- definer for the same reason doctor_sessions_on is: counting how full a window
-- is means counting other patients' bookings, which the caller's own policies
-- hide. A patient must not be able to book past a limit simply because row
-- level security stops them seeing who is already in it.
security definer
set search_path = public
as $$
declare
  v_capacity integer;
  v_booked   integer;
begin
  -- A cancellation frees a place, it never takes one.
  if new.status = 'cancelled' then
    return new;
  end if;

  -- Keyed on the window, so two patients booking different hours of the same
  -- long session never wait for each other.
  perform pg_advisory_xact_lock(
    hashtextextended(
      new.doctor_id::text || '|' || new.booked_date::text || '|'
        || new.session || '|' || new.start_time::text,
      0
    )
  );

  select s.capacity into v_capacity
    from public.doctor_sessions_on(new.doctor_id, new.booked_date) s
   where s.session    = new.session
     and s.start_time = new.start_time;

  -- No row means the doctor offers no such window that day: not on the weekly
  -- schedule, closed by an exception, or a start time that begins no window at
  -- all -- a booking assembled by hand rather than taken from what was offered.
  if v_capacity is null then
    -- The message is for the log; `hint` is the part callers match on, so a
    -- patient can be told this in their own language without the database
    -- holding a copy of one app's wording.
    raise exception 'Doctor offers no % appointment at % on %',
      new.session, new.start_time, new.booked_date
      using errcode = 'check_violation', hint = 'session_not_offered';
  end if;

  -- Counted here rather than taken from doctor_sessions_on's `booked`: that
  -- function is STABLE, so it reads the calling statement's snapshot, which was
  -- taken before this transaction waited for the lock. This count runs in a
  -- volatile trigger and sees what the transaction ahead of us committed.
  select count(*) into v_booked
    from public.bookings b
   where b.doctor_id   = new.doctor_id
     and b.booked_date = new.booked_date
     and b.session     = new.session
     and b.start_time  = new.start_time
     and b.status     <> 'cancelled'
     -- On UPDATE the row is already in the table; it must not count itself.
     and b.id is distinct from new.id;

  if v_booked >= v_capacity then
    raise exception 'This appointment is full: % of % places taken',
      v_booked, v_capacity
      using errcode = 'check_violation', hint = 'session_full';
  end if;

  return new;
end;
$$;

revoke execute on function public.enforce_session_capacity() from public;

-- start_time decides which window a booking is in, so a change to it has to be
-- re-checked against that window's capacity.
drop trigger if exists bookings_enforce_capacity on public.bookings;
create trigger bookings_enforce_capacity
  before insert or update of doctor_id, booked_date, session, start_time, status
  on public.bookings
  for each row execute function public.enforce_session_capacity();

-- -----------------------------------------------------------------------------
-- create_booking stops handing out a number.
--
-- The return type changes, so the old function has to go first rather than be
-- replaced. Everything else about it is unchanged: one transaction, so a
-- payment is never left behind by a booking the capacity trigger refused.
-- -----------------------------------------------------------------------------
drop function if exists
  public.create_booking(bigint, date, text, time, time, numeric, text);

create or replace function public.create_booking(
  p_doctor  bigint,
  p_date    date,
  p_session text,
  p_start   time,
  p_end     time,
  p_amount  numeric,
  p_method  text
)
returns table (booking_id bigint)
language plpgsql
-- definer so the capacity check behind it can count every booking in the
-- window, not just the caller's. Everything it writes is pinned to auth.uid(),
-- so it can only ever create a booking for whoever is calling it.
security definer
set search_path = public
as $$
declare
  v_patient uuid := auth.uid();
  v_payment bigint;
  v_booking bigint;
begin
  if v_patient is null then
    raise exception 'No authenticated user'
      using errcode = 'insufficient_privilege', hint = 'not_signed_in';
  end if;

  -- Said plainly here rather than let bookings_one_place_per_session surface as
  -- a duplicate key error the patient cannot read. Still one place per session
  -- rather than per window: booking two hours of the same evening is a mistake,
  -- not a use case.
  if exists (
    select 1 from public.bookings b
     where b.patient_id  = v_patient
       and b.doctor_id   = p_doctor
       and b.booked_date = p_date
       and b.session     = p_session
       and b.status     <> 'cancelled'
  ) then
    raise exception 'Patient already holds a place in this session'
      using errcode = 'unique_violation', hint = 'already_booked';
  end if;

  insert into public.payments (patient_id, amount, payment_method, status)
  values (v_patient, p_amount, p_method, 'pending')
  returning id into v_payment;

  insert into public.bookings
    (patient_id, doctor_id, payment_id, booked_date, session,
     start_time, end_time, status)
  values (v_patient, p_doctor, v_payment, p_date, p_session,
          p_start, p_end, 'confirmed')
  returning id into v_booking;

  return query select v_booking;
end;
$$;

revoke execute on function
  public.create_booking(bigint, date, text, time, time, numeric, text) from public;
grant execute on function
  public.create_booking(bigint, date, text, time, time, numeric, text)
  to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- booking_queue goes. It existed to hand a patient a number, and there is no
-- longer a number to hand them: the ranking it computed was over app bookings
-- ordered by when they were made, which is neither everyone in the room nor the
-- order the doctor calls them in.
--
-- Nothing else depends on it. The doctor dashboard reads `bookings` directly
-- and groups them itself.
-- -----------------------------------------------------------------------------
drop view if exists public.booking_queue;

-- ---- 0015_delete_my_account.sql ----
-- =============================================================================
-- A patient can delete their account from inside the app.
--
-- Apple and Google both require it of any app that creates accounts, and refuse
-- the app outright without it. It is also the right behaviour on its own terms.
--
-- What goes and what stays:
--
--   * The auth user goes. They cannot sign in again and the email is free to
--     register with afresh.
--   * The profile goes with it -- name, phone, gender, birth date -- by the
--     cascade that already exists on profiles.id.
--   * The bookings STAY, with nobody attached to them. A visit that happened is
--     the doctor's record as much as the patient's: it is what the clinic's
--     revenue and its medical history are made of. What the doctor keeps is the
--     date, the session and the outcome; who it was is gone.
--
-- Making the bookings stay is the whole of the schema change here: they are
-- currently deleted along with the patient.
--
-- Safe to re-run.
-- =============================================================================

-- A booking with no patient is the record of a deleted one, so the column has
-- to accept it.
alter table public.bookings alter column patient_id drop not null;

do $$
declare
  v_constraint text;
begin
  -- By whatever name the constraint was given, since the base schema wrote it
  -- inline and let PostgreSQL name it.
  select conname into v_constraint
    from pg_constraint
   where conrelid = 'public.bookings'::regclass
     and contype = 'f'
     and conkey = array[
       (select attnum from pg_attribute
         where attrelid = 'public.bookings'::regclass and attname = 'patient_id')
     ];

  if v_constraint is not null then
    execute format('alter table public.bookings drop constraint %I', v_constraint);
  end if;
end $$;

alter table public.bookings
  add constraint bookings_patient_id_fkey
  foreign key (patient_id) references public.profiles (id) on delete set null;

-- -----------------------------------------------------------------------------
-- The booking guard has to let the cascade through.
--
-- guard_booking_changes refuses any update that moves a booking to another
-- patient -- which is exactly what `on delete set null` does on the way out.
-- The caller is the patient themselves, so none of the existing exemptions
-- apply and the delete would fail on its own safety rule.
--
-- A transaction-local flag rather than a hole in the rule: it is set by
-- delete_my_account and by nothing else, and it is gone at commit. A patient
-- calling `update bookings set patient_id = null` by hand is still refused.
-- -----------------------------------------------------------------------------
create or replace function public.guard_booking_changes()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Deleting an account detaches its bookings on the way out. Only
  -- delete_my_account sets this, and only for its own transaction.
  if coalesce(current_setting('app.deleting_account', true), '') = 'on' then
    return new;
  end if;

  -- No JWT at all means this is not an app user: the service role, a migration,
  -- or the SQL editor. Those already have full access to the table; the rules
  -- below are about what someone signed into the apps may do. Without this the
  -- trigger locks the owner out of her own database.
  if auth.uid() is null then
    return new;
  end if;

  -- The doctor this booking is with, and an admin, decide everything about it.
  if public.is_admin() or old.doctor_id = public.current_doctor_id() then
    return new;
  end if;

  -- Nobody else may move a booking: not to another doctor, another day,
  -- another session, or another patient.
  if new.doctor_id   is distinct from old.doctor_id
     or new.patient_id  is distinct from old.patient_id
     or new.booked_date is distinct from old.booked_date
     or new.session     is distinct from old.session then
    raise exception 'A booking cannot be moved; cancel and book again'
      using errcode = 'check_violation', hint = 'booking_immutable';
  end if;

  -- And the only status a patient may set is cancelled. Whether they actually
  -- turned up is the doctor's to record.
  if new.status is distinct from old.status and new.status <> 'cancelled' then
    raise exception 'A patient may only cancel'
      using errcode = 'check_violation', hint = 'cancel_only';
  end if;

  return new;
end;
$$;

revoke execute on function public.guard_booking_changes() from public;

-- -----------------------------------------------------------------------------
-- The function the app calls.
--
-- security definer because deleting from auth.users is not something a patient
-- may do directly, and must not become something they can do to anyone else:
-- the only row it ever touches is auth.uid()'s own, named nowhere else.
-- -----------------------------------------------------------------------------
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'No authenticated user'
      using errcode = 'insufficient_privilege', hint = 'not_signed_in';
  end if;

  -- true: transaction-local, so it is gone whether this commits or rolls back.
  perform set_config('app.deleting_account', 'on', true);

  -- Everything else follows from the foreign keys already in place:
  --   profiles.id        -> on delete cascade   (the personal details go)
  --   bookings.patient_id -> on delete set null (the visits stay, anonymous)
  --   payments.patient_id -> on delete set null (the money stays, anonymous)
  --   Doctors.user_id     -> on delete set null (a doctor who deletes their
  --                          patient account is unlinked from the dashboard,
  --                          not erased from the clinic; an admin can link
  --                          them again)
  delete from auth.users where id = v_user;
end;
$$;

revoke execute on function public.delete_my_account() from public;
grant execute on function public.delete_my_account() to authenticated;

-- ---- 0016_patient_app_accounts_only.sql ----
-- =============================================================================
-- The patient app admits only the accounts it created.
--
-- All three apps sign in through the same Supabase auth, so until now a doctor
-- could open the patient app with their dashboard login and a patient could
-- open the dashboard and be shown an empty one. Neither leaks anything -- the
-- policies are per-row and hold either way -- but one login that means two
-- different people is a question every later feature has to answer, and it
-- already produced one: a doctor tapping "delete account" in the patient app
-- would take their own dashboard access with them.
--
-- An account that was not created in the patient app is a doctor's or an
-- admin's. There is nothing else: every other auth user signed up through the
-- app itself.
--
-- Safe to re-run.
-- =============================================================================

create or replace function public.is_patient_account()
returns boolean
language sql
stable
-- definer: the caller must be able to ask this about themselves before the app
-- will let them in, and reading the doctor and admin tables to find out is not
-- something their own policies would allow.
security definer
set search_path = public
as $$
  select auth.uid() is not null
     and not exists (
       select 1 from public."Doctors" d where d.user_id = auth.uid()
     )
     and not exists (
       select 1 from public.admins a where a.id = auth.uid()
     );
$$;

revoke execute on function public.is_patient_account() from public;
grant execute on function public.is_patient_account() to authenticated;

-- ---- 0017_profile_photo.sql ----
-- =============================================================================
-- A patient can put a photograph on their own profile.
--
-- The column is new; the bucket is the second one this project keeps, after
-- banners, and its rules are the opposite shape: banners are written by one
-- administrator and read by everyone, while these are written by many people
-- who must each be confined to their own.
--
-- That confinement is the whole of the storage policy: the first folder of the
-- object's path has to be the writer's own user id. Without it any signed-in
-- patient could overwrite anybody's photograph, since one bucket is one
-- namespace.
--
-- Safe to re-run.
-- =============================================================================

alter table public.profiles add column if not exists image text;

comment on column public.profiles.image is
  'Public URL of the patient''s own photograph, or null. Written by the app '
  'after an upload to the avatars bucket.';

do $$
begin
  if to_regclass('storage.buckets') is null then
    raise notice 'storage schema not present -- skipping bucket setup';
    return;
  end if;

  -- public: a photograph is shown wherever the patient's own name is, so it is
  -- served straight from the CDN rather than through a signed URL per view.
  insert into storage.buckets (id, name, public)
  values ('avatars', 'avatars', true)
  on conflict (id) do nothing;

  -- foldername(name) splits the path; [1] is the first folder. Requiring it to
  -- be the caller's own id is what keeps one patient out of another's files.
  execute 'drop policy if exists avatars_insert_own on storage.objects';
  execute $p$
    create policy avatars_insert_own on storage.objects
      for insert to authenticated
      with check (
        bucket_id = 'avatars'
        and (storage.foldername(name))[1] = auth.uid()::text
      )
  $p$;

  -- Replacing a photograph is an update when the path is reused.
  execute 'drop policy if exists avatars_update_own on storage.objects';
  execute $p$
    create policy avatars_update_own on storage.objects
      for update to authenticated
      using (
        bucket_id = 'avatars'
        and (storage.foldername(name))[1] = auth.uid()::text
      )
      with check (
        bucket_id = 'avatars'
        and (storage.foldername(name))[1] = auth.uid()::text
      )
  $p$;

  execute 'drop policy if exists avatars_delete_own on storage.objects';
  execute $p$
    create policy avatars_delete_own on storage.objects
      for delete to authenticated
      using (
        bucket_id = 'avatars'
        and (storage.foldername(name))[1] = auth.uid()::text
      )
  $p$;
end $$;

